typedef struct Node { int key; int val; struct Node* next; } Node;
typedef struct { Node* buckets[1009]; } MyHashMap;

MyHashMap* myHashMapCreate() {
    MyHashMap* obj = (MyHashMap*)malloc(sizeof(MyHashMap));
    return obj;
}

void myHashMapPut(MyHashMap* obj, int key, int value) {
    int h = key % 1009;
    for (Node* p = obj->buckets[h]; p; p = p->next)
        if (p->key == key) { p->val = value; return; }
    Node* n = (Node*)malloc(sizeof(Node));
    n->key = key; n->val = value; n->next = obj->buckets[h];
    obj->buckets[h] = n;
}

struct Node* cloneGraph(struct Node* s) {
    if (s == NULL) return NULL;
    struct Node* hit = lookup(s);
    if (hit) return hit;
    struct Node* c = (struct Node*)calloc(1, sizeof(struct Node));
    c->val = s->val;
    c->numNeighbors = s->numNeighbors;
    c->neighbors = (struct Node**)calloc(s->numNeighbors, sizeof(struct Node*));
    for (int i = 0; i < s->numNeighbors; i++)
        c->neighbors[i] = cloneGraph(s->neighbors[i]);
    insert(s, c);
    return c;
}
